const flag=(value:boolean)=>cat(text('bool'),Uint8Array.of(+value));
const string=(value:string)=>cat(text('TEXT'),unicode(value));
const padded=(value:Uint8Array)=>cat(value,Buffer.alloc((4-value.length%4)%4));
const section=(name:string,data:Uint8Array)=>cat(text('8BIM'+name),u32(data.length),padded(data));
